     1→import { useEffect, useState } from "react";
     2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
     3→import { useLoaderData, useFetcher } from "react-router";
     4→import { useAppBridge } from "@shopify/app-bridge-react";
     5→import { authenticate } from "../shopify.server";
     6→import db from "../db.server";
     7→
     8→// ---------------------------------------------------------------------------
     9→// Types
    10→// ---------------------------------------------------------------------------
    11→
    12→interface LocalConfig {
    13→  displayMode: string;
    14→  position: string;
    15→  triggerType: string;
    16→  primaryColor: string;
    17→  successColor: string;
    18→  errorColor: string;
    19→  backgroundColor: string;
    20→  textColor: string;
    21→  borderRadius: string;
    22→  heading: string;
    23→  placeholder: string;
    24→  buttonText: string;
    25→  successMessage: string;
    26→  errorMessage: string;
    27→  showRecommender: boolean;
    28→  customCss: string;
    29→}
    30→
    31→// ---------------------------------------------------------------------------
    32→// Loader
    33→// ---------------------------------------------------------------------------
    34→
    35→export const loader = async ({ request }: LoaderFunctionArgs) => {
    36→  const { session } = await authenticate.admin(request);
    37→  const config = await db.widgetConfig.findUnique({ where: { shop: session.shop } });
    38→
    39→  return {
    40→    config: config ?? {
    41→      displayMode: "popup",
    42→      position: "bottom-right",
    43→      triggerType: "button",
    44→      primaryColor: "#000000",
    45→      successColor: "#16a34a",
    46→      errorColor: "#dc2626",
    47→      backgroundColor: "#ffffff",
    48→      textColor: "#111111",
    49→      borderRadius: "8",
    50→      heading: "Size Guide",
    51→      placeholder: "Select your size",
    52→      buttonText: "Find My Size",
    53→      successMessage: "This size should fit you well!",
    54→      errorMessage: "We couldn't determine your size. Please refer to the chart.",
    55→      showRecommender: true,
    56→      customCss: "",
    57→    },
    58→  };
    59→};
    60→
    61→// ---------------------------------------------------------------------------
    62→// Action
    63→// ---------------------------------------------------------------------------
    64→
    65→export const action = async ({ request }: ActionFunctionArgs) => {
    66→  const { session } = await authenticate.admin(request);
    67→  const formData = await request.formData();
    68→
    69→  try {
    70→    const data = {
    71→      displayMode: (formData.get("displayMode") as string) || "popup",
    72→      position: (formData.get("position") as string) || "bottom-right",
    73→      triggerType: (formData.get("triggerType") as string) || "button",
    74→      primaryColor: (formData.get("primaryColor") as string) || "#000000",
    75→      successColor: (formData.get("successColor") as string) || "#16a34a",
    76→      errorColor: (formData.get("errorColor") as string) || "#dc2626",
    77→      backgroundColor: (formData.get("backgroundColor") as string) || "#ffffff",
    78→      textColor: (formData.get("textColor") as string) || "#111111",
    79→      borderRadius: (formData.get("borderRadius") as string) || "8",
    80→      heading: (formData.get("heading") as string) || "Size Guide",
    81→      placeholder: (formData.get("placeholder") as string) || "Select your size",
    82→      buttonText: (formData.get("buttonText") as string) || "Find My Size",
    83→      successMessage: (formData.get("successMessage") as string) || "This size should fit you well!",
    84→      errorMessage: (formData.get("errorMessage") as string) || "We couldn't determine your size.",
    85→      showRecommender: formData.get("showRecommender") === "true",
    86→      customCss: (formData.get("customCss") as string) || "",
    87→    };
    88→
    89→    await db.widgetConfig.upsert({
    90→      where: { shop: session.shop },
    91→      update: data,
    92→      create: { shop: session.shop, ...data },
    93→    });
    94→    return { ok: true, message: "Widget settings saved" };
    95→  } catch (error) {
    96→    return {
    97→      error: error instanceof Error ? error.message : "An unexpected error occurred",
    98→    };
    99→  }
   100→};
   101→
   102→// ---------------------------------------------------------------------------
   103→// Shared input styles
   104→// ---------------------------------------------------------------------------
   105→
   106→const INPUT_STYLE: React.CSSProperties = {
   107→  padding: "8px 12px",
   108→  border: "1px solid #8c9196",
   109→  borderRadius: "8px",
   110→  fontSize: "14px",
   111→  width: "100%",
   112→  outline: "none",
   113→  boxSizing: "border-box",
   114→  fontFamily: "inherit",
   115→  color: "#202223",
   116→  backgroundColor: "#fff",
   117→  transition: "border-color 0.2s",
   118→};
   119→
   120→const LABEL_STYLE: React.CSSProperties = {
   121→  fontWeight: 600,
   122→  fontSize: "13px",
   123→  color: "#202223",
   124→  marginBottom: "4px",
   125→  display: "block",
   126→};
   127→
   128→const FIELD_STYLE: React.CSSProperties = {
   129→  display: "flex",
   130→  flexDirection: "column",
   131→  gap: "4px",
   132→  width: "100%",
   133→};
   134→
   135→// ---------------------------------------------------------------------------
   136→// Sub-components
   137→// ---------------------------------------------------------------------------
   138→
   139→function FieldLabel({ children }: { children: React.ReactNode }) {
   140→  return <span style={LABEL_STYLE}>{children}</span>;
   141→}
   142→
   143→function TextInput({
   144→  value,
   145→  onChange,
   146→  placeholder,
   147→}: {
   148→  value: string;
   149→  onChange: (v: string) => void;
   150→  placeholder?: string;
   151→}) {
   152→  return (
   153→    <input
   154→      type="text"
   155→      value={value}
   156→      onChange={(e) => onChange(e.target.value)}
   157→      placeholder={placeholder}
   158→      style={INPUT_STYLE}
   159→      onFocus={(e) => {
   160→        (e.currentTarget as HTMLInputElement).style.borderColor = "#005bd3";
   161→      }}
   162→      onBlur={(e) => {
   163→        (e.currentTarget as HTMLInputElement).style.borderColor = "#8c9196";
   164→      }}
   165→    />
   166→  );
   167→}
   168→
   169→function ColorPickerField({
   170→  label,
   171→  value,
   172→  onChange,
   173→}: {
   174→  label: string;
   175→  value: string;
   176→  onChange: (v: string) => void;
   177→}) {
   178→  return (
   179→    <s-box padding="base" borderWidth="base" borderRadius="base">
   180→      <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
   181→        <FieldLabel>{label}</FieldLabel>
   182→        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
   183→          <div
   184→            style={{
   185→              width: "32px",
   186→              height: "32px",
   187→              borderRadius: "6px",
   188→              backgroundColor: value,
   189→              border: "1px solid #c9cccf",
   190→              position: "relative",
   191→              overflow: "hidden",
   192→              flexShrink: 0,
   193→              cursor: "pointer",
   194→            }}
   195→          >
   196→            <input
   197→              type="color"
   198→              value={value}
   199→              onChange={(e) => onChange(e.target.value)}
   200→              style={{
   201→                position: "absolute",
   202→                inset: 0,
   203→                opacity: 0,
   204→                width: "100%",
   205→                height: "100%",
   206→                cursor: "pointer",
   207→                padding: 0,
   208→                border: "none",
   209→              }}
   210→            />
   211→          </div>
   212→          <input
   213→            type="text"
   214→            value={value}
   215→            onChange={(e) => onChange(e.target.value)}
   216→            maxLength={7}
   217→            style={{
   218→              ...INPUT_STYLE,
   219→              width: "90px",
   220→              fontFamily: "monospace",
   221→              fontSize: "13px",
   222→            }}
   223→          />
   224→        </div>
   225→      </div>
   226→    </s-box>
   227→  );
   228→}
   229→
   230→function DisplayModeCard({
   231→  value,
   232→  label,
   233→  description,
   234→  benefit,
   235→  selected,
   236→  onSelect,
   237→}: {
   238→  value: string;
   239→  label: string;
   240→  description: string;
   241→  benefit: string;
   242→  selected: boolean;
   243→  onSelect: (v: string) => void;
   244→}) {
   245→  return (
   246→    <div
   247→      onClick={() => onSelect(value)}
   248→      style={{
   249→        flex: "1 1 0",
   250→        padding: "16px",
   251→        borderRadius: "8px",
   252→        border: selected ? "2px solid #005bd3" : "1px solid #c9cccf",
   253→        backgroundColor: selected ? "#f0f5ff" : "#fff",
   254→        cursor: "pointer",
   255→        transition: "border-color 0.2s, background-color 0.2s",
   256→        minWidth: "140px",
   257→      }}
   258→    >
   259→      <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
   260→        <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
   261→          <div
   262→            style={{
   263→              width: "10px",
   264→              height: "10px",
   265→              borderRadius: "50%",
   266→              border: selected ? "3px solid #005bd3" : "2px solid #8c9196",
   267→              backgroundColor: selected ? "#005bd3" : "transparent",
   268→              flexShrink: 0,
   269→            }}
   270→          />
   271→          <span style={{ fontWeight: 600, fontSize: "14px", color: "#202223" }}>
   272→            {label}
   273→          </span>
   274→          {selected && (
   275→            <span
   276→              style={{
   277→                fontSize: "11px",
   278→                backgroundColor: "#005bd3",
   279→                color: "#fff",
   280→                borderRadius: "4px",
   281→                padding: "1px 6px",
   282→                marginLeft: "auto",
   283→              }}
   284→            >
   285→              Active
   286→            </span>
   287→          )}
   288→        </div>
   289→        <span style={{ fontSize: "13px", color: "#6d7175" }}>{description}</span>
   290→        <span style={{ fontSize: "12px", color: "#005bd3", fontWeight: 500 }}>
   291→          Best for: {benefit}
   292→        </span>
   293→      </div>
   294→    </div>
   295→  );
   296→}
   297→
   298→function PositionGrid({
   299→  value,
   300→  onChange,
   301→}: {
   302→  value: string;
   303→  onChange: (v: string) => void;
   304→}) {
   305→  const positions = [
   306→    { id: "top-left", label: "Top Left" },
   307→    { id: "top-right", label: "Top Right" },
   308→    { id: "bottom-left", label: "Bottom Left" },
   309→    { id: "bottom-right", label: "Bottom Right" },
   310→  ];
   311→
   312→  return (
   313→    <div
   314→      style={{
   315→        display: "grid",
   316→        gridTemplateColumns: "1fr 1fr",
   317→        gap: "8px",
   318→        maxWidth: "320px",
   319→      }}
   320→    >
   321→      {positions.map((pos) => {
   322→        const selected = value === pos.id;
   323→        return (
   324→          <div
   325→            key={pos.id}
   326→            onClick={() => onChange(pos.id)}
   327→            style={{
   328→              padding: "12px 16px",
   329→              borderRadius: "8px",
   330→              border: selected ? "2px solid #005bd3" : "1px solid #c9cccf",
   331→              backgroundColor: selected ? "#f0f5ff" : "#fff",
   332→              cursor: "pointer",
   333→              textAlign: "center",
   334→              fontSize: "13px",
   335→              fontWeight: selected ? 600 : 400,
   336→              color: selected ? "#005bd3" : "#202223",
   337→              transition: "all 0.15s",
   338→            }}
   339→          >
   340→            {pos.label}
   341→          </div>
   342→        );
   343→      })}
   344→    </div>
   345→  );
   346→}
   347→
   348→function TriggerTypeSelector({
   349→  value,
   350→  onChange,
   351→}: {
   352→  value: string;
   353→  onChange: (v: string) => void;
   354→}) {
   355→  const types = [
   356→    { id: "button", label: "Button", desc: "Prominent CTA button" },
   357→    { id: "link", label: "Link", desc: "Subtle text link" },
   358→    { id: "tab", label: "Tab", desc: "Sticky tab on the edge" },
   359→  ];
   360→
   361→  return (
   362→    <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
   363→      {types.map((t) => {
   364→        const selected = value === t.id;
   365→        return (
   366→          <div
   367→            key={t.id}
   368→            onClick={() => onChange(t.id)}
   369→            style={{
   370→              padding: "10px 16px",
   371→              borderRadius: "8px",
   372→              border: selected ? "2px solid #005bd3" : "1px solid #c9cccf",
   373→              backgroundColor: selected ? "#f0f5ff" : "#fff",
   374→              cursor: "pointer",
   375→              transition: "all 0.15s",
   376→            }}
   377→          >
   378→            <div style={{ fontWeight: 600, fontSize: "13px", color: selected ? "#005bd3" : "#202223" }}>
   379→              {t.label}
   380→            </div>
   381→            <div style={{ fontSize: "12px", color: "#6d7175", marginTop: "2px" }}>
   382→              {t.desc}
   383→            </div>
   384→          </div>
   385→        );
   386→      })}
   387→    </div>
   388→  );
   389→}
   390→
   391→// ---------------------------------------------------------------------------
   392→// Live Preview
   393→// ---------------------------------------------------------------------------
   394→
   395→function WidgetPreview({ config }: { config: LocalConfig }) {
   396→  const radius = `${config.borderRadius}px`;
   397→
   398→  return (
   399→    <div
   400→      style={{
   401→        backgroundColor: config.backgroundColor,
   402→        borderRadius: radius,
   403→        border: `1px solid ${config.primaryColor}33`,
   404→        padding: "20px",
   405→        fontFamily: "system-ui, sans-serif",
   406→        boxShadow: "0 4px 16px rgba(0,0,0,0.08)",
   407→        maxWidth: "320px",
   408→        width: "100%",
   409→      }}
   410→    >
   411→      {/* Header */}
   412→      <div
   413→        style={{
   414→          borderBottom: `1px solid ${config.primaryColor}22`,
   415→          paddingBottom: "12px",
   416→          marginBottom: "16px",
   417→          display: "flex",
   418→          alignItems: "center",
   419→          justifyContent: "space-between",
   420→        }}
   421→      >
   422→        <span
   423→          style={{
   424→            fontSize: "16px",
   425→            fontWeight: 700,
   426→            color: config.textColor,
   427→          }}
   428→        >
   429→          {config.heading || "Size Guide"}
   430→        </span>
   431→        <span
   432→          style={{
   433→            fontSize: "18px",
   434→            color: "#8c9196",
   435→            cursor: "pointer",
   436→            lineHeight: 1,
   437→          }}
   438→        >
   439→          ×
   440→        </span>
   441→      </div>
   442→
   443→      {/* Size Chart Table */}
   444→      <div
   445→        style={{
   446→          borderRadius: "6px",
   447→          overflow: "hidden",
   448→          border: "1px solid #e3e5e7",
   449→          marginBottom: "16px",
   450→        }}
   451→      >
   452→        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "12px" }}>
   453→          <thead>
   454→            <tr style={{ backgroundColor: `${config.primaryColor}15` }}>
   455→              {["Size", "S", "M", "L", "XL"].map((h) => (
   456→                <th
   457→                  key={h}
   458→                  style={{
   459→                    padding: "8px 10px",
   460→                    textAlign: "center",
   461→                    fontWeight: 600,
   462→                    color: config.textColor,
   463→                    borderRight: "1px solid #e3e5e7",
   464→                  }}
   465→                >
   466→                  {h}
   467→                </th>
   468→              ))}
   469→            </tr>
   470→          </thead>
   471→          <tbody>
   472→            {[
   473→              { label: "Bust", values: ["32", "34", "36", "38"] },
   474→              { label: "Waist", values: ["26", "28", "30", "32"] },
   475→              { label: "Hips", values: ["34", "36", "38", "40"] },
   476→            ].map((row, ri) => (
   477→              <tr
   478→                key={row.label}
   479→                style={{ backgroundColor: ri % 2 === 0 ? "#fff" : "#f9fafb" }}
   480→              >
   481→                <td
   482→                  style={{
   483→                    padding: "7px 10px",
   484→                    fontWeight: 600,
   485→                    color: config.textColor,
   486→                    borderRight: "1px solid #e3e5e7",
   487→                    borderTop: "1px solid #e3e5e7",
   488→                    fontSize: "11px",
   489→                  }}
   490→                >
   491→                  {row.label}
   492→                </td>
   493→                {row.values.map((v, vi) => (
   494→                  <td
   495→                    key={vi}
   496→                    style={{
   497→                      padding: "7px 10px",
   498→                      textAlign: "center",
   499→                      color: config.textColor,
   500→                      borderRight: "1px solid #e3e5e7",
   501→                      borderTop: "1px solid #e3e5e7",
   502→                      fontSize: "11px",
   503→                    }}
   504→                  >
   505→                    {v}"
   506→                  </td>
   507→                ))}
   508→              </tr>
   509→            ))}
   510→          </tbody>
   511→        </table>
   512→      </div>
   513→
   514→      {/* CTA Button */}
   515→      {config.showRecommender && (
   516→        <button
   517→          style={{
   518→            width: "100%",
   519→            padding: "10px 16px",
   520→            backgroundColor: config.primaryColor,
   521→            color: "#fff",
   522→            border: "none",
   523→            borderRadius: radius,
   524→            fontSize: "14px",
   525→            fontWeight: 600,
   526→            cursor: "pointer",
   527→            marginBottom: "12px",
   528→          }}
   529→        >
   530→          {config.buttonText || "Find My Size"}
   531→        </button>
   532→      )}
   533→
   534→      {/* Success Message */}
   535→      <div
   536→        style={{
   537→          backgroundColor: `${config.successColor}15`,
   538→          border: `1px solid ${config.successColor}40`,
   539→          borderRadius: "6px",
   540→          padding: "10px 12px",
   541→          display: "flex",
   542→          alignItems: "flex-start",
   543→          gap: "8px",
   544→        }}
   545→      >
   546→        <span style={{ color: config.successColor, fontSize: "14px", flexShrink: 0 }}>✓</span>
   547→        <span style={{ fontSize: "12px", color: config.textColor, lineHeight: 1.4 }}>
   548→          {config.successMessage || "This size should fit you well!"}
   549→        </span>
   550→      </div>
   551→
   552→      {/* Footer badge */}
   553→      <div
   554→        style={{
   555→          marginTop: "12px",
   556→          textAlign: "center",
   557→          fontSize: "10px",
   558→          color: "#8c9196",
