   567→// ---------------------------------------------------------------------------
   568→// Main Component
   569→// ---------------------------------------------------------------------------
   570→
   571→export default function WidgetCustomizer() {
   572→  const { config: serverConfig } = useLoaderData<typeof loader>();
   573→  const fetcher = useFetcher<typeof action>();
   574→  const shopify = useAppBridge();
   575→
   576→  const [config, setConfig] = useState<LocalConfig>({
   577→    displayMode: serverConfig.displayMode,
   578→    position: serverConfig.position,
   579→    triggerType: serverConfig.triggerType,
   580→    primaryColor: serverConfig.primaryColor,
   581→    successColor: serverConfig.successColor,
   582→    errorColor: serverConfig.errorColor,
   583→    backgroundColor: serverConfig.backgroundColor,
   584→    textColor: serverConfig.textColor,
   585→    borderRadius: serverConfig.borderRadius,
   586→    heading: serverConfig.heading,
   587→    placeholder: serverConfig.placeholder,
   588→    buttonText: serverConfig.buttonText,
   589→    successMessage: serverConfig.successMessage,
   590→    errorMessage: serverConfig.errorMessage,
   591→    showRecommender: serverConfig.showRecommender,
   592→    customCss: serverConfig.customCss,
   593→  });
   594→
   595→  const isLoading = fetcher.state !== "idle";
   596→
   597→  useEffect(() => {
   598→    if (fetcher.data && "ok" in fetcher.data) {
   599→      shopify.toast.show(fetcher.data.message ?? "Widget settings saved");
   600→    } else if (fetcher.data && "error" in fetcher.data) {
   601→      shopify.toast.show(fetcher.data.error ?? "Failed to save settings", { isError: true });
   602→    }
   603→  }, [fetcher.data, shopify]);
   604→
   605→  const updateConfig = (key: keyof LocalConfig, value: string | boolean) => {
   606→    setConfig((prev) => ({ ...prev, [key]: value }));
   607→  };
   608→
   609→  const handleSave = () => {
   610→    const formData = new FormData();
   611→    formData.set("displayMode", config.displayMode);
   612→    formData.set("position", config.position);
   613→    formData.set("triggerType", config.triggerType);
   614→    formData.set("primaryColor", config.primaryColor);
   615→    formData.set("successColor", config.successColor);
   616→    formData.set("errorColor", config.errorColor);
   617→    formData.set("backgroundColor", config.backgroundColor);
   618→    formData.set("textColor", config.textColor);
   619→    formData.set("borderRadius", config.borderRadius);
   620→    formData.set("heading", config.heading);
   621→    formData.set("placeholder", config.placeholder);
   622→    formData.set("buttonText", config.buttonText);
   623→    formData.set("successMessage", config.successMessage);
   624→    formData.set("errorMessage", config.errorMessage);
   625→    formData.set("showRecommender", config.showRecommender ? "true" : "false");
   626→    formData.set("customCss", config.customCss);
   627→    fetcher.submit(formData, { method: "post" });
   628→  };
   629→
   630→  const showPosition = config.displayMode === "popup" || config.displayMode === "both";
   631→
   632→  return (
   633→    <s-page heading="Widget Customizer">
   634→
   635→      <s-button slot="primary-action" variant="primary" onClick={handleSave} loading={isLoading}>
   636→        Save changes
   637→      </s-button>
   638→
   639→      {/* ------------------------------------------------------------------ */}
   640→      {/* Section 1 — Display Mode                                           */}
   641→      {/* ------------------------------------------------------------------ */}
   642→      <s-section heading="Display Mode">
   643→        <s-stack direction="block" gap="base">
   644→          <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
   645→            <DisplayModeCard
   646→              value="popup"
   647→              label="Popup"
