   457→
   458→export default function WidgetCustomizer() {
   459→  const { config: serverConfig } = useLoaderData<typeof loader>();
   460→  const fetcher = useFetcher<typeof action>();
   461→  const shopify = useAppBridge();
   462→
   463→  const [config, setConfig] = useState<LocalConfig>({
   464→    displayMode: serverConfig.displayMode,
   465→    position: serverConfig.position,
   466→    triggerType: serverConfig.triggerType,
   467→    primaryColor: serverConfig.primaryColor,
   468→    successColor: serverConfig.successColor,
   469→    errorColor: serverConfig.errorColor,
   470→    backgroundColor: serverConfig.backgroundColor,
   471→    textColor: serverConfig.textColor,
   472→    borderRadius: serverConfig.borderRadius,
   473→    heading: serverConfig.heading,
   474→    placeholder: serverConfig.placeholder,
   475→    buttonText: serverConfig.buttonText,
   476→    successMessage: serverConfig.successMessage,
   477→    errorMessage: serverConfig.errorMessage,
   478→    showRecommender: serverConfig.showRecommender,
   479→    customCss: serverConfig.customCss,
   480→  });
   481→
   482→  const isLoading = fetcher.state !== "idle";
   483→
   484→  useEffect(() => {
   485→    if (fetcher.data && "ok" in fetcher.data) {
   486→      shopify.toast.show(fetcher.data.message ?? "Widget settings saved");
   487→    } else if (fetcher.data && "error" in fetcher.data) {
   488→      shopify.toast.show(fetcher.data.error ?? "Failed to save settings", { isError: true });
   489→    }
   490→  }, [fetcher.data, shopify]);
   491→
   492→  const updateConfig = (key: keyof LocalConfig, value: string | boolean) => {
   493→    setConfig((prev) => ({ ...prev, [key]: value }));
   494→  };
   495→
   496→  const handleSave = () => {
   497→    const formData = new FormData();
   498→    formData.set("displayMode", config.displayMode);
   499→    formData.set("position", config.position);
   500→    formData.set("triggerType", config.triggerType);
   501→    formData.set("primaryColor", config.primaryColor);
   502→    formData.set("successColor", config.successColor);
   503→    formData.set("errorColor", config.errorColor);
   504→    formData.set("backgroundColor", config.backgroundColor);
   505→    formData.set("textColor", config.textColor);
   506→    formData.set("borderRadius", config.borderRadius);
   507→    formData.set("heading", config.heading);
   508→    formData.set("placeholder", config.placeholder);
   509→    formData.set("buttonText", config.buttonText);
   510→    formData.set("successMessage", config.successMessage);
   511→    formData.set("errorMessage", config.errorMessage);
   512→    formData.set("showRecommender", config.showRecommender ? "true" : "false");
   513→    formData.set("customCss", config.customCss);
   514→    fetcher.submit(formData, { method: "post" });
   515→  };
   516→
   517→  const showPosition = config.displayMode === "popup" || config.displayMode === "both";
   518→
   519→  return (
   520→    <s-page heading="Widget Customizer">
   521→
   522→      <s-button slot="primary-action" variant="primary" onClick={handleSave} loading={isLoading}>
   523→        Save changes
   524→      </s-button>
   525→
   526→      {/* ------------------------------------------------------------------ */}
   527→      {/* Section 1 — Display Mode                                           */}
   528→      {/* ------------------------------------------------------------------ */}
   529→      <s-section heading="Display Mode">
   530→        <s-stack direction="inline" gap="base">
   531→          <DisplayModeCard
   532→            value="popup"
   533→            label="Popup"
   534→            description="Opens as a modal overlay when triggered"
   535→            benefit="clean product pages"
   536→            selected={config.displayMode === "popup"}
   537→            onSelect={(v) => updateConfig("displayMode", v)}
   538→          />
   539→          <DisplayModeCard
   540→            value="inline"
   541→            label="Inline"
   542→            description="Embedded directly in the product page"
   543→            benefit="detailed size info"
   544→            selected={config.displayMode === "inline"}
   545→            onSelect={(v) => updateConfig("displayMode", v)}
   546→          />
   547→          <DisplayModeCard
   548→            value="both"
   549→            label="Both"
   550→            description="Inline summary with popup for full chart"
   551→            benefit="maximum visibility"
   552→            selected={config.displayMode === "both"}
   553→            onSelect={(v) => updateConfig("displayMode", v)}
   554→          />
   555→        </s-stack>
   556→      </s-section>
   557→
   558→      {/* ------------------------------------------------------------------ */}
   559→      {/* Section 2 — Trigger Settings                                       */}
   560→      {/* ------------------------------------------------------------------ */}
   561→      <s-section heading="Trigger Settings">
   562→        <s-stack direction="block" gap="base">
   563→          <s-stack direction="block" gap="small-200">
   564→            <s-text>Trigger style</s-text>
   565→            <TriggerTypeSelector
   566→              value={config.triggerType}
   567→              onChange={(v) => updateConfig("triggerType", v)}
   568→            />
   569→          </s-stack>
   570→
   571→          {showPosition && (
   572→            <s-stack direction="block" gap="small-200">
   573→              <s-text>Popup position</s-text>
   574→              <PositionGrid
   575→                value={config.position}
   576→                onChange={(v) => updateConfig("position", v)}
   577→              />
   578→            </s-stack>
   579→          )}
   580→        </s-stack>
   581→      </s-section>
   582→
   583→      {/* ------------------------------------------------------------------ */}
   584→      {/* Section 3 — Colors                                                 */}
   585→      {/* ------------------------------------------------------------------ */}
   586→      <s-section heading="Colors">
   587→        <s-stack direction="inline" gap="base">
   588→          <ColorPickerField
   589→            label="Primary Color"
   590→            value={config.primaryColor}
   591→            onChange={(v) => updateConfig("primaryColor", v)}
   592→          />
   593→          <ColorPickerField
   594→            label="Background Color"
   595→            value={config.backgroundColor}
   596→            onChange={(v) => updateConfig("backgroundColor", v)}
   597→          />
   598→          <ColorPickerField
   599→            label="Text Color"
   600→            value={config.textColor}
   601→            onChange={(v) => updateConfig("textColor", v)}
   602→          />
   603→          <ColorPickerField
   604→            label="Success Color"
   605→            value={config.successColor}
   606→            onChange={(v) => updateConfig("successColor", v)}
   607→          />
   608→          <ColorPickerField
   609→            label="Error Color"
   610→            value={config.errorColor}
   611→            onChange={(v) => updateConfig("errorColor", v)}
   612→          />
   613→        </s-stack>
   614→      </s-section>
